toolScript:
// DOM Elements
        const video = document.getElementById('videoElement');
        const canvas = document.getElementById('canvasElement');
        const ctx = canvas.getContext('2d');
        const instructionText = document.getElementById('instruction-text');
        const btnCapture = document.getElementById('btn-capture');
        const btnStart = document.getElementById('btn-start');
        const resetContainer = document.getElementById('reset-container');
        const resultDisplayTotal = document.getElementById('result-display-total');
        const resultDisplayDual = document.getElementById('result-display-dual');
        const cameraGuide = document.getElementById('camera-guide');
        const container = document.querySelector('.cam-container');
        const loupe = document.getElementById('loupe');
        // State Variables
        let stream = null;
        let clickStep = 0; // 0: None, 1: Card L, 2: Card R, 3: Nose, 4: Pupil L, 5: Pupil R
        let points = {
            cardLeft: null,
            cardRight: null,
            nose: null,
            pupilLeft: null,
            pupilRight: null
        };
        // 5-Step Process
        const stepsInfo = [
            "Camera Active. Align card on forehead.",
            "Click the exact LEFT edge of the card.",
            "Click the exact RIGHT edge of the card.",
            "Click the center of your NOSE BRIDGE.",
            "Click the center of your LEFT pupil (screen left).",
            "Click the center of your RIGHT pupil (screen right)."
        ];
        async function startCamera() {
            try {
                stream = await navigator.mediaDevices.getUserMedia({
                    video: {
                        facingMode: 'user',
                        width: { ideal: 1280 },
                        height: { ideal: 720 }
                    }
                });
                video.srcObject = stream;
                btnStart.classList.add('hidden');
                btnCapture.disabled = false;
                cameraGuide.classList.remove('hidden');
                instructionText.innerText = "Hold a standard card against your forehead. Look at the camera.";
                video.style.display = 'block';
                canvas.style.display = 'none';

                const lightingFeedback = document.getElementById('lighting-feedback');
                if (lightingFeedback) lightingFeedback.classList.remove('hidden');
                startLightingCheck();
            } catch (err) {
                console.error("Camera Error:", err);
                showToast("Error: Camera access denied. Check browser permissions.");
            }
        }
        function captureImage() {
            canvas.width = video.videoWidth;
            canvas.height = video.videoHeight;
            ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
            stopLightingCheck();
            stream.getTracks().forEach(track => track.stop());
            video.style.display = 'none';
            canvas.style.display = 'block';
            cameraGuide.classList.add('hidden');
            document.getElementById('lighting-feedback')?.classList.add('hidden');
            const dataUrl = canvas.toDataURL();
            loupe.style.backgroundImage = `url(${dataUrl})`;
            btnCapture.classList.add('hidden');
            resetContainer.classList.remove('hidden');
            clickStep = 1;
            updateInstructionUI();
            // Listeners
            canvas.addEventListener('mousedown', handleCanvasClick);
            canvas.addEventListener('touchstart', (e) => {
                e.preventDefault();
                handleCanvasClick(e.touches[0]);
            }, { passive: false });
            // Loupe Listeners
            container.addEventListener('mousemove', moveLoupe);
            container.addEventListener('touchmove', (e) => moveLoupe(e.touches[0]), { passive: false });
            container.addEventListener('mouseleave', () => loupe.style.display = 'none');
            container.addEventListener('touchend', () => loupe.style.display = 'none');
        }
        function moveLoupe(e) {
            if (clickStep === 0 || clickStep > 5) {
                loupe.style.display = 'none';
                return;
            }
            const rect = canvas.getBoundingClientRect();
            // Client position
            let clientX = e.clientX;
            let clientY = e.clientY;
            // Relative position inside canvas
            const x = clientX - rect.left;
            const y = clientY - rect.top;
            if (x < 0 || y < 0 || x > rect.width || y > rect.height) {
                loupe.style.display = 'none';
                return;
            }
            loupe.style.display = 'block';
            // Position the loupe physically near the cursor (offset so it doesn't block the actual click)
            loupe.style.left = (x - 70) + 'px';
            loupe.style.top = (y - 160) + 'px'; // Float above cursor
            // Shift the background to match cursor position
            const pctX = (x / rect.width) * 100;
            const pctY = (y / rect.height) * 100;
            // Zoom level 3x
            loupe.style.backgroundSize = `${rect.width * 3}px ${rect.height * 3}px`;
            loupe.style.backgroundPosition = `${pctX}% ${pctY}%`;
        }
        function handleCanvasClick(e) {
            if (clickStep === 0 || clickStep > 5) return;
            const rect = canvas.getBoundingClientRect();
            const scaleX = canvas.width / rect.width;
            const scaleY = canvas.height / rect.height;
            const x = (e.clientX - rect.left) * scaleX;
            const y = (e.clientY - rect.top) * scaleY;
            drawPoint(x, y, clickStep);
            // Data capture sequence
            if (clickStep === 1) points.cardLeft = { x, y };
            if (clickStep === 2) points.cardRight = { x, y };
            if (clickStep === 3) points.nose = { x, y };
            if (clickStep === 4) points.pupilLeft = { x, y };
            if (clickStep === 5) {
                points.pupilRight = { x, y };
                loupe.style.display = 'none'; // Hide loupe
                calculatePD();
            }
            clickStep++;
            if (clickStep <= 5) updateInstructionUI();
        }
        function updateInstructionUI() {
            instructionText.innerHTML = `<span class='step-badge'>${clickStep}</span> ${stepsInfo[clickStep]}`;
            instructionText.className = "text-center text-white font-bold text-sm mt-5 font-mono bg-blue-600 p-3 rounded-lg shadow-lg";
        }
        function drawPoint(x, y, step) {
            ctx.beginPath();
            ctx.arc(x, y, 8, 0, 2 * Math.PI);
            if (step <= 2) {
                ctx.fillStyle = '#3b82f6'; // Blue for Card
            } else if (step === 3) {
                ctx.fillStyle = '#f59e0b'; // Yellow for Nose
            } else {
                ctx.fillStyle = '#10b981'; // Green for Pupils
            }
            ctx.strokeStyle = 'white';
            ctx.fill();
            ctx.lineWidth = 3;
            ctx.stroke();
        }
        function calculatePD() {
            const CARD_WIDTH_MM = 85.60;
            const IRIS_MM = 11.7;
            const useIris = window.useIrisMode;

            const refDistPx = Math.sqrt(
                Math.pow(points.cardRight.x - points.cardLeft.x, 2) +
                Math.pow(points.cardRight.y - points.cardLeft.y, 2)
            );
            const mmPerPx = (useIris ? IRIS_MM : CARD_WIDTH_MM) / refDistPx;

            const pupilDistPx = Math.sqrt(
                Math.pow(points.pupilRight.x - points.pupilLeft.x, 2) +
                Math.pow(points.pupilRight.y - points.pupilLeft.y, 2)
            );
            const totalPD = pupilDistPx * mmPerPx;
            const leftPD = Math.abs(points.nose.x - points.pupilLeft.x) * mmPerPx;
            const rightPD = Math.abs(points.pupilRight.x - points.nose.x) * mmPerPx;

            window.measurementResults = {
                totalPD, leftPD, rightPD,
                useIrisMode: useIris,
                date: new Date().toISOString()
            };

            resultDisplayTotal.innerText = `${totalPD.toFixed(1)} mm`;
            resultDisplayDual.innerText = `Dual PD: L ${leftPD.toFixed(1)} / R ${rightPD.toFixed(1)}`;
            resultDisplayTotal.style.color = '#10b981';
            instructionText.innerText = "Measurement Complete!";
            instructionText.className = "text-center text-emerald-400 text-sm mt-5 font-mono bg-slate-800 p-3 rounded-lg border border-slate-700";

            ctx.lineWidth = 3;
            ctx.beginPath();
            ctx.moveTo(points.cardLeft.x, points.cardLeft.y);
            ctx.lineTo(points.cardRight.x, points.cardRight.y);
            ctx.strokeStyle = useIris ? 'rgba(139, 92, 246, 0.6)' : 'rgba(59, 130, 246, 0.6)';
            ctx.stroke();

            ctx.beginPath();
            ctx.moveTo(points.pupilLeft.x, points.pupilLeft.y);
            ctx.lineTo(points.pupilRight.x, points.pupilRight.y);
            ctx.strokeStyle = 'rgba(16, 185, 129, 0.8)';
            ctx.stroke();

            ctx.beginPath();
            ctx.moveTo(points.nose.x, points.nose.y - 40);
            ctx.lineTo(points.nose.x, points.nose.y + 40);
            ctx.strokeStyle = 'rgba(245, 158, 11, 0.8)';
            ctx.setLineDash([5, 5]);
            ctx.stroke();
            ctx.setLineDash([]);

            updateFrameSuggestions(totalPD);
            updateNearPD();

            document.getElementById('download-section')?.classList.remove('hidden');
            showToast("Success! Dual PD Calculated.");
        }
        function resetTool() {
            clickStep = 0;
            points = { cardLeft: null, cardRight: null, nose: null, pupilLeft: null, pupilRight: null };
            stopLightingCheck();
            resetContainer.classList.add('hidden');
            document.getElementById('download-section')?.classList.add('hidden');
            btnStart.classList.remove('hidden');
            btnCapture.classList.remove('hidden');
            btnCapture.disabled = true;
            video.style.display = 'block';
            canvas.style.display = 'none';
            loupe.style.display = 'none';
            cameraGuide.classList.add('hidden');
            document.getElementById('lighting-feedback')?.classList.add('hidden');
            resultDisplayTotal.innerText = "-- mm";
            resultDisplayTotal.style.color = 'white';
            resultDisplayDual.innerText = "Dual PD: -- / --";
            instructionText.innerText = "Press 'Start Camera' to begin calibration.";
            instructionText.className = "text-center text-slate-400 text-sm mt-5 font-mono bg-slate-800 p-3 rounded-lg border border-slate-700";
            ctx.clearRect(0, 0, canvas.width, canvas.height);
        }
        function showToast(msg) {
            const toast = document.createElement('div');
            toast.className = "fixed top-24 left-1/2 -translate-x-1/2 bg-slate-800 text-white px-8 py-3 rounded-full shadow-2xl z-[100] animate-bounce font-black text-xs uppercase tracking-widest border border-blue-500 text-center max-w-[90vw]";
            toast.innerText = msg;
            document.body.appendChild(toast);
            setTimeout(() => toast.remove(), 4000);
        }

        function stopLightingCheck() {
            if (window.lightingInterval) {
                cancelAnimationFrame(window.lightingInterval);
                window.lightingInterval = null;
            }
        }

        function startLightingCheck() {
            stopLightingCheck();

            function checkLighting() {
                if (!stream || !video.videoWidth || !video.videoHeight) {
                    window.lightingInterval = requestAnimationFrame(checkLighting);
                    return;
                }

                try {
                    const tempCanvas = document.createElement('canvas');
                    tempCanvas.width = video.videoWidth;
                    tempCanvas.height = video.videoHeight;
                    const tempCtx = tempCanvas.getContext('2d');

                    if (video.readyState < 2) {
                        window.lightingInterval = requestAnimationFrame(checkLighting);
                        return;
                    }

                    tempCtx.drawImage(video, 0, 0);

                    const imageData = tempCtx.getImageData(0, 0, tempCanvas.width, tempCanvas.height);
                    const data = imageData.data;
                    const width = tempCanvas.width;
                    const height = tempCanvas.height;

                    let totalBrightness = 0;
                    let skinTonePixels = 0;
                    let leftSkin = 0, rightSkin = 0, topSkin = 0, bottomSkin = 0;
                    let leftDiagonal = 0, rightDiagonal = 0;
                    const centerX = Math.floor(width / 2);
                    const centerY = Math.floor(height / 2);
                    const step = 10;

                    for (let y = 0; y < height; y += step) {
                        for (let x = 0; x < width; x += step) {
                            const i = (y * width + x) * 4;
                            const r = data[i];
                            const g = data[i + 1];
                            const b = data[i + 2];
                            const brightness = (r + g + b) / 3;
                            totalBrightness += brightness;

                            if (r > 95 && g > 40 && b > 20 && r > g && r > b && Math.abs(r - g) > 15) {
                                skinTonePixels++;
                                if (x < centerX) leftSkin++;
                                if (x >= centerX) rightSkin++;
                                if (y < centerY) topSkin++;
                                if (y >= centerY) bottomSkin++;
                                const isLeftOfCenter = x < centerX;
                                const isAboveCenter = y < centerY;
                                if (isLeftOfCenter === isAboveCenter) leftDiagonal++;
                                else rightDiagonal++;
                            }
                        }
                    }

                    const pixelCount = (width / step) * (height / step);
                    const avgBrightness = totalBrightness / pixelCount;
                    const skinRatio = skinTonePixels / pixelCount;

                    let tiltAngle = 0;
                    if (skinTonePixels > 50) {
                        const diagonalDiff = Math.abs(leftDiagonal - rightDiagonal);
                        const diagonalSum = leftDiagonal + rightDiagonal;
                        if (diagonalSum > 0) {
                            const asymmetry = diagonalDiff / diagonalSum;
                            tiltAngle = Math.round(Math.min(asymmetry * 45, 45));
                        }
                        if (leftDiagonal > rightDiagonal) tiltAngle = -tiltAngle;
                    }

                    const lightingEl = document.getElementById('lighting-status');
                    const positionEl = document.getElementById('position-status');
                    const tiltEl = document.getElementById('tilt-status');

                    if (avgBrightness > 50 && avgBrightness < 200) {
                        lightingEl.className = 'status-indicator status-good';
                        lightingEl.innerHTML = '<span class="w-2 h-2 rounded-full bg-current animate-pulse"></span><span>Good</span>';
                    } else if (avgBrightness <= 50) {
                        lightingEl.className = 'status-indicator status-bad';
                        lightingEl.innerHTML = '<span class="w-2 h-2 rounded-full bg-current"></span><span>Too Dark</span>';
                    } else {
                        lightingEl.className = 'status-indicator status-warning';
                        lightingEl.innerHTML = '<span class="w-2 h-2 rounded-full bg-current"></span><span>Too Bright</span>';
                    }

                    if (skinRatio < 0.05) {
                        positionEl.className = 'status-indicator status-bad';
                        positionEl.innerHTML = '<span class="w-2 h-2 rounded-full bg-current"></span><span>No Face</span>';
                    } else {
                        const leftRatio = leftSkin / skinTonePixels;
                        const topRatio = topSkin / skinTonePixels;
                        const isCentered = leftRatio > 0.3 && leftRatio < 0.7 && topRatio > 0.25 && topRatio < 0.6;

                        if (isCentered && skinRatio > 0.1) {
                            positionEl.className = 'status-indicator status-good';
                            positionEl.innerHTML = '<span class="w-2 h-2 rounded-full bg-current animate-pulse"></span><span>Centered</span>';
                        } else if (leftRatio < 0.3) {
                            positionEl.className = 'status-indicator status-warning';
                            positionEl.innerHTML = '<span class="w-2 h-2 rounded-full bg-current"></span><span>Too Left</span>';
                        } else if (leftRatio > 0.7) {
                            positionEl.className = 'status-indicator status-warning';
                            positionEl.innerHTML = '<span class="w-2 h-2 rounded-full bg-current"></span><span>Too Right</span>';
                        } else if (topRatio < 0.25) {
                            positionEl.className = 'status-indicator status-warning';
                            positionEl.innerHTML = '<span class="w-2 h-2 rounded-full bg-current"></span><span>Too High</span>';
                        } else if (topRatio > 0.6) {
                            positionEl.className = 'status-indicator status-warning';
                            positionEl.innerHTML = '<span class="w-2 h-2 rounded-full bg-current"></span><span>Too Low</span>';
                        } else {
                            positionEl.className = 'status-indicator status-good';
                            positionEl.innerHTML = '<span class="w-2 h-2 rounded-full bg-current animate-pulse"></span><span>Centered</span>';
                        }
                    }

                    if (tiltEl) {
                        const tiltAngleEl = tiltEl.querySelector('#tilt-angle') || document.getElementById('tilt-angle');
                        if (tiltAngleEl) tiltAngleEl.textContent = tiltAngle + '°';
                        if (Math.abs(tiltAngle) < 5) {
                            tiltEl.className = 'status-indicator status-good';
                        } else if (Math.abs(tiltAngle) < 15) {
                            tiltEl.className = 'status-indicator status-warning';
                        } else {
                            tiltEl.className = 'status-indicator status-bad';
                        }
                    }
                } catch (e) {
                    // CORS errors - ignore
                }
                window.lightingInterval = requestAnimationFrame(checkLighting);
            }

            setTimeout(() => {
                window.lightingInterval = requestAnimationFrame(checkLighting);
            }, 300);
        }

        function updateFrameSuggestions(pd) {
            const minWidth = Math.round(pd + 30);
            const maxWidth = Math.round(pd + 40);
            const frameElement = document.getElementById('frame-suggestion');
            const noteElement = document.getElementById('frame-note');
            if (!frameElement) return;
            if (window.currentUnit === 'in') {
                const minIn = (minWidth / 25.4).toFixed(1);
                const maxIn = (maxWidth / 25.4).toFixed(1);
                frameElement.textContent = `${minIn} - ${maxIn} inches`;
                if (noteElement) noteElement.textContent = `Based on your PD, look for frames with a total width of ${minIn}-${maxIn} inches for optimal fit.`;
            } else {
                frameElement.textContent = `${minWidth} - ${maxWidth} mm`;
                if (noteElement) noteElement.textContent = `Based on your PD, look for frames with a total width of ${minWidth}-${maxWidth}mm for optimal fit.`;
            }
        }

        function setUnit(unit) {
            window.currentUnit = unit;
            document.querySelectorAll('.unit-btn').forEach(btn => {
                if (btn.dataset.unit === unit) {
                    btn.classList.add('bg-blue-600', 'text-white');
                    btn.classList.remove('bg-slate-700', 'text-slate-300');
                } else {
                    btn.classList.remove('bg-blue-600', 'text-white');
                    btn.classList.add('bg-slate-700', 'text-slate-300');
                }
            });
            if (window.measurementResults) {
                updateFrameSuggestions(window.measurementResults.totalPD);
            }
        }

        function updateNearPD() {
            const slider = document.getElementById('distance-slider');
            if (!slider) return;
            const distance = parseInt(slider.value);
            document.getElementById('distance-value').textContent = distance;
            if (!window.measurementResults) return;
            const adjustment = Math.max(0, (distance - 40) * 0.05);
            const nearPD = Math.max(window.measurementResults.totalPD - adjustment, window.measurementResults.totalPD - 5);
            const diff = window.measurementResults.totalPD - nearPD;
            const nearEl = document.getElementById('near-pd-result');
            const diffEl = document.getElementById('pd-diff');
            if (nearEl) nearEl.textContent = `${nearPD.toFixed(1)} mm`;
            if (diffEl) diffEl.textContent = diff.toFixed(1);
        }

        function switchFeatureTab(tab) {
            document.querySelectorAll('.feature-tab').forEach(t => t.classList.remove('active'));
            event.target.classList.add('active');
            document.querySelectorAll('.feature-panel').forEach(p => p.classList.add('hidden'));
            const panel = document.getElementById(tab + '-section');
            if (panel) panel.classList.remove('hidden');
        }

        function enableIrisMode() {
            window.useIrisMode = true;
            showToast("Iris Mode enabled. Use your iris as the reference scale.");
            resetTool();
        }

        function generatePhoneQR() {
            const currentUrl = window.location.href.split('?')[0];
            const phoneUrl = currentUrl + '?mode=phone&source=' + Date.now();
            const modal = document.createElement('div');
            modal.className = 'phone-connect-modal';
            modal.innerHTML = `
                <div class="qr-container relative">
                    <button onclick="this.closest('.phone-connect-modal').remove()" class="absolute top-2 right-2 text-slate-400 hover:text-slate-600 bg-transparent border-0 cursor-pointer">
                        <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"></path></svg>
                    </button>
                    <h3 class="text-xl font-bold text-slate-800 mb-2">Scan with Your Phone</h3>
                    <p class="text-slate-500 text-sm mb-4">Open this URL on your phone to use its camera as the scanner</p>
                    <div class="qr-code">
                        <img src="https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=${encodeURIComponent(phoneUrl)}" alt="QR Code" class="w-48 h-48">
                    </div>
                    <p class="text-slate-400 text-xs mt-4 break-all">${phoneUrl}</p>
                </div>
            `;
            document.body.appendChild(modal);
        }

        function downloadPDReport() {
            if (!window.measurementResults) {
                showToast("No measurement data to export.");
                return;
            }
            const { jsPDF } = window.jspdf;
            if (!jsPDF) {
                showToast("PDF library loading...");
                return;
            }
            const doc = new jsPDF();
            doc.setFillColor(59, 130, 246);
            doc.rect(0, 0, 210, 40, 'F');
            doc.setTextColor(255, 255, 255);
            doc.setFontSize(24);
            doc.setFont('helvetica', 'bold');
            doc.text('PD Measurement Report', 20, 25);
            doc.setFontSize(10);
            doc.setFont('helvetica', 'normal');
            doc.text('Toolkit Gen', 20, 33);
            doc.setTextColor(100, 100, 100);
            doc.setFontSize(10);
            doc.text(`Generated: ${new Date().toLocaleDateString()}`, 20, 50);
            doc.setTextColor(0, 0, 0);
            doc.setFontSize(16);
            doc.setFont('helvetica', 'bold');
            doc.text('Measurement Results', 20, 65);
            doc.setFontSize(12);
            doc.setFont('helvetica', 'normal');
            doc.setFillColor(248, 250, 252);
            doc.rect(20, 70, 170, 25, 'F');
            doc.setFont('helvetica', 'bold');
            doc.text('Total PD (Binocular):', 25, 82);
            doc.setFontSize(20);
            doc.text(`${window.measurementResults.totalPD.toFixed(1)} mm`, 100, 84);
            doc.setFontSize(12);
            doc.setFillColor(248, 250, 252);
            doc.rect(20, 100, 82, 25, 'F');
            doc.rect(108, 100, 82, 25, 'F');
            doc.setFont('helvetica', 'bold');
            doc.text('Left PD:', 25, 112);
            doc.text(`${window.measurementResults.leftPD?.toFixed(1) || '--'} mm`, 25, 120);
            doc.text('Right PD:', 113, 112);
            doc.text(`${window.measurementResults.rightPD?.toFixed(1) || '--'} mm`, 113, 120);
            doc.setFontSize(14);
            doc.setTextColor(0, 0, 0);
            doc.setFont('helvetica', 'bold');
            doc.text('Recommended Frame Width', 20, 140);
            const minWidth = Math.round(window.measurementResults.totalPD + 30);
            const maxWidth = Math.round(window.measurementResults.totalPD + 40);
            doc.setFontSize(11);
            doc.setFont('helvetica', 'normal');
            doc.text(`Based on your PD, look for frames with a total width of ${minWidth}-${maxWidth}mm`, 20, 150);
            doc.setFillColor(255, 245, 245);
            doc.rect(20, 220, 170, 30, 'F');
            doc.setDrawColor(254, 205, 211);
            doc.rect(20, 220, 170, 30, 'S');
            doc.setFontSize(8);
            doc.setTextColor(153, 27, 27);
            doc.text('DISCLAIMER: For informational purposes only. Consult an eye care professional.', 25, 230);
            doc.text('Toolkit Gen - toolkitgen.com/tool/pupillary_distance_cam', 20, 285);
            doc.save(`PD-Report-${new Date().toISOString().split('T')[0]}.pdf`);
            showToast("PDF Report Downloaded!");
        }

        window.currentUnit = 'mm';
        window.measurementResults = null;
        window.useIrisMode = false;
